SELECT t.id || ' — не названы операции: ' || string_agg(DISTINCT ro.operation, ', ') AS detail FROM project_plan_tasks t JOIN task_requirement tr ON tr.project_id = t.project_id AND tr.task_id = t.id JOIN project_requirement_op ro ON ro.project_id = t.project_id AND ro.requirement_id = tr.requirement_id LEFT JOIN project_task_operation tо ON tо.project_id = t.project_id AND tо.task_id = t.id AND tо.operation = ro.operation WHERE t.project_id = $1 AND t.kind = 'dev' AND tо.operation IS NULL GROUP BY t.id ORDER BY t.id
